<script setup lang="ts">import MarketStateIcon from './MarketStateIcon.vue';import type {MarketHomeIconState} from '@/utils/marketHomeIcons';import type {AlertEvent} from '@/types/market';defineProps<{availability:string;events:AlertEvent[]}>();defineEmits<{open:[event:AlertEvent]}>();const label=(e:AlertEvent)=>e.result_codes.length===2?'双向观察':e.result_codes[0]==='buy'?'买观察':'卖观察';const state=(e:AlertEvent):MarketHomeIconState=>e.result_codes.length===2?'aligned':e.result_codes[0]==='buy'?'up':'down'</script>
<template><aside class="rail"><h2>HTDY Focus</h2><p v-if="availability==='unavailable'">HTDY 当前 Event 暂不可用；不能据此判断本时段无观察。</p><p v-else-if="!events.length">当前交易日暂无 HTDY 正式观察 Event</p><button v-for="event in events" :key="event.id" @click="$emit('open',event)"><MarketStateIcon :state="state(event)" size="micro"/><span><b>{{event.symbol.toUpperCase()}} · {{label(event)}} · {{event.frequency}}</b><small>{{event.rule_code}} · {{event.contract}}<br>bar {{event.bar_end}} · detected {{event.detected_at}}<br>transport attempted {{event.notification_attempted_at??'—'}}</small></span></button></aside></template>
